#!/usr/bin/env node
// GENERATED by scripts/gen/build.mjs from gen/resilience.rules.js - edit the sources, not this file.
const anyFile = (files, re) => files.some((f) => f.cs && re.test(f.text));
const firstFile = (files, re) => files.find((f) => f.cs && re.test(f.text));

const RULES = [
  {
    id: "RES001",
    level: "medium",
    re: /\bnew\s+HttpClient\s*\(/,
    msg: "HttpClient created directly (no pooling, no resilience handler)",
    fix: "Register with AddHttpClient and AddStandardResilienceHandler().",
  },
  {
    id: "RES002",
    level: "medium",
    project: (files) => {
      const f = firstFile(files, /\.AddHttpClient\s*[<(]/);
      return f &&
        !anyFile(
          files,
          /AddStandardResilienceHandler|AddStandardHedgingHandler|AddResilienceHandler|AddPolicyHandler/,
        )
        ? [{ file: f.rel }]
        : [];
    },
    msg: "HttpClients registered but no resilience handler anywhere",
    fix: "Add .AddStandardResilienceHandler() (timeouts, retry, circuit breaker) from Microsoft.Extensions.Http.Resilience.",
  },
  {
    id: "RES003",
    level: "medium",
    project: (files) => {
      const f = firstFile(files, /AddStandardResilienceHandler|AddStandardHedgingHandler/);
      return f &&
        !anyFile(
          files,
          /DisableForUnsafeHttpMethods|Retry\.DisableFor|DisableFor\s*\(\s*HttpMethod/,
        )
        ? [{ file: f.rel }]
        : [];
    },
    msg: "Standard resilience handler retries ALL methods unless told otherwise (POST/PUT/PATCH/DELETE too)",
    fix: "options.Retry.DisableForUnsafeHttpMethods() unless the downstream call is idempotent (idempotency key).",
  },
  {
    id: "RES004",
    level: "medium",
    re: /\.Timeout\s*=\s*(Timeout\.InfiniteTimeSpan|TimeSpan\.MaxValue|System\.Threading\.Timeout\.InfiniteTimeSpan)/,
    msg: "Infinite HTTP timeout",
    fix: "Set a finite per-attempt and total timeout (resilience handler) and pass the request CancellationToken.",
  },
  {
    id: "RES005",
    level: "medium",
    multi: /catch\s*(\([^)]*\))?\s*\{\s*\}/g,
    msg: "Empty catch swallows failures",
    fix: "Handle, log with the exception object, or rethrow; swallow only a specific, documented exception type.",
  },
  {
    id: "RES006",
    level: "low",
    re: /\bTask\.Delay\s*\(\s*[^,()]*(\([^)]*\))?[^,()]*\)\s*[;)]/,
    msg: "Task.Delay without a CancellationToken",
    fix: "Pass stoppingToken so shutdown is not delayed.",
  },
  {
    id: "RES007",
    level: "medium",
    re: /^\s*_\s*=\s*(Task\.Run\s*\(|\w[\w.]*Async\s*\()/,
    msg: "Fire-and-forget task (failures unobserved, lost on shutdown)",
    fix: "Use a hosted BackgroundService with a Channel<T> queue, or await it.",
  },
  {
    id: "RES008",
    level: "medium",
    fn: (text) =>
      /:\s*BackgroundService\b/.test(text) &&
      /ExecuteAsync/.test(text) &&
      !/catch\s*(\(|\{)/.test(text)
        ? [text.split("\n").findIndex((l) => /ExecuteAsync/.test(l)) + 1]
        : [],
    msg: "BackgroundService.ExecuteAsync without any catch (one failure stops the host or the loop silently)",
    fix: "Catch and log per iteration, honour stoppingToken, and decide the BackgroundServiceExceptionBehavior deliberately.",
  },
  {
    id: "RES009",
    level: "medium",
    fn: (text) =>
      /:\s*BackgroundService\b/.test(text)
        ? text
            .split("\n")
            .flatMap((l, i) =>
              /GetRequiredService\s*<\s*\w*(DbContext|Repository)\w*\s*>|private\s+readonly\s+\w*DbContext\b/.test(
                l,
              )
                ? [i + 1]
                : [],
            )
        : [],
    msg: "Scoped service (DbContext) used from a BackgroundService singleton",
    fix: "Inject IServiceScopeFactory (or IDbContextFactory) and create a scope per unit of work.",
  },
  {
    id: "RES010",
    level: "low",
    re: /\bwhile\s*\(\s*true\s*\)/,
    msg: "while (true) loop",
    fix: "Loop on !stoppingToken.IsCancellationRequested (or PeriodicTimer) so the service stops cleanly.",
  },
];

// Heuristic, regex-based scan of a .NET repo (.cs and appsettings*.json). It finds candidates, not proof:
// read every hit in context before changing code. Skips bin/obj/node_modules/.git and test projects.
// Usage: node <this-file> [path] [--json] [--strict]    (--strict: exit 1 when any HIGH finding exists)
import { readdirSync, readFileSync } from "node:fs";
import { join, relative } from "node:path";

const args = process.argv.slice(2);
const root = args.find((a) => !a.startsWith("--")) ?? process.cwd();
const SKIP = new Set(["bin", "obj", "node_modules", ".git", ".vs", "TestResults"]);
const isTest = (rel) => /(^|[\\/])[^\\/]*\.?tests?([\\/]|\.)/i.test(rel);

function* walk(dir) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) {
      if (!SKIP.has(e.name)) yield* walk(join(dir, e.name));
    } else if (/\.cs$|(^|[\\/])appsettings[^\\/]*\.json$/i.test(e.name)) yield join(dir, e.name);
  }
}
const lineOf = (text, index) => text.slice(0, index).split("\n").length;

const files = [];
for (const abs of walk(root)) {
  const rel = relative(root, abs).split("\\").join("/");
  if (!isTest(rel)) files.push({ rel, text: readFileSync(abs, "utf8"), cs: abs.endsWith(".cs") });
}

const findings = [];
const add = (r, file, line) =>
  findings.push({ id: r.id, level: r.level, file, line, msg: r.msg, fix: r.fix });
for (const r of RULES) {
  if (r.project) {
    for (const hit of r.project(files)) add(r, hit.file, hit.line ?? 1);
    continue;
  }
  for (const f of files) {
    if (r.json ? f.cs : !f.cs) continue;
    if (r.re) {
      f.text.split("\n").forEach((l, i) => {
        if (f.cs && l.trimStart().startsWith("//")) return;
        if (r.re.test(l)) add(r, f.rel, i + 1);
      });
    } else if (r.multi) {
      for (const m of f.text.matchAll(r.multi)) add(r, f.rel, lineOf(f.text, m.index));
    } else if (r.fn) {
      for (const line of r.fn(f.text, f.rel)) add(r, f.rel, line);
    }
  }
}

const order = { high: 0, medium: 1, low: 2 };
findings.sort(
  (a, b) => order[a.level] - order[b.level] || a.file.localeCompare(b.file) || a.line - b.line,
);
if (args.includes("--json")) console.log(JSON.stringify(findings, null, 2));
else {
  for (const f of findings)
    console.log(
      `${f.file}:${f.line}  ${f.level.toUpperCase()}  ${f.id}  ${f.msg}\n    fix: ${f.fix}`,
    );
  const n = (l) => findings.filter((f) => f.level === l).length;
  console.log(
    `\n${files.length} files scanned: ${n("high")} high, ${n("medium")} medium, ${n("low")} low.`,
  );
}
if (args.includes("--strict") && findings.some((f) => f.level === "high")) process.exit(1);
